<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesListRef;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentUserVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRelyingPartyVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentTrustedClientVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesUidVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesRoleVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesVersionVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesItem;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentVersionVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Application\Usecase\Create\UserRoleAssignmentCreateResult;
use PHPUnit\Framework\TestCase;

final class UserRoleAssignmentCreateResultUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new UserRoleAssignmentCreateResult();
        $userOneValue = new UserRef('one');
        $userOtherValue = new UserRef('other');
        $copy = $value->user($userOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new UserRef('one'), $value->getUser());
        $this->assertNotEquals(new UserRef('other'), $value->getUser());
        $this->assertEquals(new UserRef('one'), $value->getUserOrCurrent(UserRoleAssignmentUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('other'), $value->getUserOrCurrent(UserRoleAssignmentUserVO::from($userOtherValue))->value());
        $value->unsetUser();
        $this->assertEquals(new UserRef('other'), $value->getUserOrCurrent(UserRoleAssignmentUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('one'), $value->getUserOrCurrent(UserRoleAssignmentUserVO::from($userOtherValue))->value());
        $relyingPartyOneValue = new RelyingPartyRef('one');
        $relyingPartyOtherValue = new RelyingPartyRef('other');
        $copy = $value->relyingParty($relyingPartyOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new RelyingPartyRef('one'), $value->getRelyingParty());
        $this->assertNotEquals(new RelyingPartyRef('other'), $value->getRelyingParty());
        $this->assertEquals(new RelyingPartyRef('one'), $value->getRelyingPartyOrCurrent(UserRoleAssignmentRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $this->assertNotEquals(new RelyingPartyRef('other'), $value->getRelyingPartyOrCurrent(UserRoleAssignmentRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $value->unsetRelyingParty();
        $this->assertEquals(new RelyingPartyRef('other'), $value->getRelyingPartyOrCurrent(UserRoleAssignmentRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $this->assertNotEquals(new RelyingPartyRef('one'), $value->getRelyingPartyOrCurrent(UserRoleAssignmentRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $trustedClientOneValue = new TrustedClientRef('one');
        $trustedClientOtherValue = new TrustedClientRef('other');
        $copy = $value->trustedClient($trustedClientOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClient());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClient());
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClientOrCurrent(UserRoleAssignmentTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClientOrCurrent(UserRoleAssignmentTrustedClientVO::from($trustedClientOtherValue))->value());
        $value->unsetTrustedClient();
        $this->assertEquals(new TrustedClientRef('other'), $value->getTrustedClientOrCurrent(UserRoleAssignmentTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('one'), $value->getTrustedClientOrCurrent(UserRoleAssignmentTrustedClientVO::from($trustedClientOtherValue))->value());
        $rolesOneValue = new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        ));
        $rolesOtherValue = new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('other'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('other')),
            UserRoleAssignmentRolesVersionVO::from(2)
        ));
        $copy = $value->roles($rolesOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )), $value->getRoles());
        $this->assertNotEquals(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('other'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('other')),
            UserRoleAssignmentRolesVersionVO::from(2)
        )), $value->getRoles());
        $this->assertEquals(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )), $value->getRolesOrCurrent(UserRoleAssignmentRolesVO::from($rolesOtherValue))->value());
        $this->assertNotEquals(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('other'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('other')),
            UserRoleAssignmentRolesVersionVO::from(2)
        )), $value->getRolesOrCurrent(UserRoleAssignmentRolesVO::from($rolesOtherValue))->value());
        $value->unsetRoles();
        $this->assertEquals(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('other'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('other')),
            UserRoleAssignmentRolesVersionVO::from(2)
        )), $value->getRolesOrCurrent(UserRoleAssignmentRolesVO::from($rolesOtherValue))->value());
        $this->assertNotEquals(new UserRoleAssignmentRolesListRef(new UserRoleAssignmentRolesItem(
            UserRoleAssignmentRolesUidVO::from('one'),
            UserRoleAssignmentRolesRoleVO::from(new RoleRef('one')),
            UserRoleAssignmentRolesVersionVO::from(1)
        )), $value->getRolesOrCurrent(UserRoleAssignmentRolesVO::from($rolesOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(UserRoleAssignmentVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(UserRoleAssignmentVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(UserRoleAssignmentVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(UserRoleAssignmentVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
